 <div className="catalog-summary"><p className="atlas-note">{matches} {query||category!=='All'?'matching':'retained source'} {matches===1?'outcome':'outcomes'} · {groups.length} {groups.length===1?'group':'groups'}</p>{!wide&&<button className="catalog-find" onPointerDown={e=>e.preventDefault()} aria-expanded={searchOpen||!!query} aria-controls="catalog-find-field" onClick={()=>{if(searchOpen||query){keyboard.hide();setQuery('');setSearchOpen(false)}else setSearchOpen(true)}}><MagnifyingGlassIcon/>{searchOpen||query?'Close search':'Find a prop'}</button>}</div>
